body.usercss:

.changeFormId {
    background:url('/resource/ux/formbuilder/default/images/bg.png') repeat scroll center 0 / auto 100%;
    display:none;
    position:absolute;
    z-index:50;
}
.changeFormId input {
    border: 0 none;
    color: #333;
    font-size: 1em;
    font-weight: 500;
    line-height: 40px;
    padding: 0 0 0 15px;
    width: 216px;
}

.changeFormId .button{
    cursor: pointer;
    display: block;
    float: right;
}

userscript.function:

        	SUX.root = SUX.getModuleTop().SUX.root;

            if(Sepoa.request.form_id){
                window.defaultJsonData = JSON.stringify(Sepoa.cache.form.get(Sepoa.request.form_id));
            }

            app = $sObject.app = dhtmlxApp.start("formbuilder", formBuilderBox);
            dhtmlxEvent(window, "unload", function() {
                app.unload();
            });

            Sepoa.attachEvent("onWindowResize", resize);
			resize();
			this.readyStatus = true;

			if(Sepoa.request.form_id){
				doQuery(Sepoa.request.form_id);
			}

			var changeFormId = document.createElement("div");
			changeFormId.setAttribute("class", "changeFormId");

			var keyword = document.createElement("input");
			keyword.setAttribute("type", "text");
			keyword.setAttribute("id", "keyword");
			keyword.setAttribute("name", "keyword");
			keyword.setAttribute("placeholder", "insert FORM ID");

			changeFormId.appendChild(keyword);

			var inputFormIdCloseDiv = document.createElement("div");
			inputFormIdCloseDiv.setAttribute("class", "dhx_cell_hdr_icon dhx_cell_hdr_icon_cancel button cancelImg");
			inputFormIdCloseDiv.setAttribute("id", "inputFormIdClose");

			changeFormId.appendChild(inputFormIdCloseDiv);

			var setFormIdDiv = document.createElement("div");
			setFormIdDiv.setAttribute("class", "dhx_cell_hdr_icon dhx_cell_hdr_icon_add button okImg");
			setFormIdDiv.setAttribute("id", "setFormId");

			changeFormId.appendChild(setFormIdDiv);
			formBuilderBox.appendChild(changeFormId);

			$("#inputFormIdClose").on("click", function(){
				inputFormIdClose();
			});

			$("#setFormId").on("click", function(){
				setFormId();
			});


            if(Sepoa.info.HOUSE_CODE != "000"){
                Alert("not have permission");
                return;
            }
        	if($(".changeFormId").css("display") != "none"){
				Alert(Sepoa.cache.text.get("AD_041_2.NOT_CONFIRM_FORM_ID"));
				return;	
			}

			if(myLayout.cells("a").getText() == ""){
				Alert(Sepoa.cache.text.get("AD_041_2.NOT_FOUND_ID"));
				return;
			}

			Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(flag){
				if(flag){
					var e = myMockup.exportToFormSepoaMode(null, {hideIds:true});

		            var jsonData = e.data;
		            blockNameReplacer(jsonData);

					dataOutput.setValue("FORM_ID", myLayout.cells("a").getText());
					dataOutput.setValue("FORM_JSON",JSON.stringify(jsonData));
					if(!!e.slang){
			        	dataOutput.setValue("form_slang",JSON.stringify(e.slang));
			        }

					doServiceAjax("sepoa.svc.admin.AD_041_2", "TRANSACTION", "doSave", null, function(so){
						if(so.status == "1"){
							Sepoa.cache.clear();
							Message(Sepoa.cache.text.get("MESSAGE.0001"));
							jsonDataImoprt({form_id:dataOutput.getValue("FORM_ID")});
							callFunction(['p'],'refreshList');
						}else{
							Alert(so.message);
						}
						dataOutput.setValue("FORM_JSON","");
					});
				}
			});


        	if(myLayout.cells("a").getText() == ""){
				Alert(Sepoa.cache.text.get("AD_041_2.NOT_FOUND_ID"));
				return;
			}
			dataOutput.setValue("FORM_ID", myLayout.cells("a").getText());
			Confirm(Sepoa.cache.text.get("MESSAGE.1015"), function(status){
				if(status){
					var nickName = "sepoa.svc.admin.AD_041_2";
					var conType = "TRANSACTION";
					var methodName = "doDelete";
					doServiceAjax( nickName, conType, methodName, null,function(so){
						if(so.status == "1"){
							Message(Sepoa.cache.text.get("MESSAGE.0001"));
							callFunction(['p'],'refreshList');
							clearApp(false);
						}else{
							Alert(so.message);
						}		
					});
				}
			})


        	var form_id = myLayout.cells("a").getText();
			if(form_id == "") return;

			PopupOpenPostReal(window.CONTEXT_NAME + '/Admin/MultiLanguageManagement/AdminMultiLanguageManagementLayout.sux'
							, window.screen.width
							, window.screen.height
							, form_id
							, {LANGUAGE_ID:form_id}
							, true);


inputFormIdClose();
var jsonData = Sepoa.cache.form.get(formId);
blockNameReplacer(jsonData);
app.callEvent("onDataImport", [JSON.stringify(jsonData || [])]);
myLayout.cells("a").setText(formId);


var finder = ['block', 'fieldset'];

for (var idx in data) {
    if (finder.indexOf(data[idx].type) + 1) {
        if (data[idx].list) {
            blockNameReplacer(data[idx].list);
        }

        if (!data[idx].name) {
            data[idx].name = createNewID();
        }
    }
}


var x52 = function(n){
    if(n > 25){
        n += 6;
    }
    return String.fromCharCode(65+n);
}

var a = i % 52
var b = (i - a) / 52
if(b > 51){
    return x52(a) + convert52digits(b);
}else{
    return x52(a);
}
